        .ToList();

    private IReadOnlyList<KySoRow> PagedItems => FilteredItems
        .Skip((CurrentPage - 1) * PageSize)
        .Take(PageSize)
        .ToList();

    private int SelectedCount => AllItems.Count(x => x.IsSelected);
    private bool IsAllSelected => PagedItems.Any() && PagedItems.All(x => x.IsSelected);

    private void ResetFilters()
    {
        SelectedGrade = Grades.First();
        SelectedClass = ClassesByGrade[SelectedGrade].First();
        SelectedSubject = string.Empty;
        SearchText = string.Empty;
        CurrentPage = 1;
    }

    private void SignSelected()
    {
        foreach (var item in AllItems.Where(x => x.IsSelected))
        {
            item.SignStatus = "Đã ký";
